sql_query:
SELECT "Name of ICI"
FROM clinical_trials
WHERE LOWER(TRIM(COALESCE("Name of ICI", ''))) NOT IN ('', 'none', 'null', 'nan') AND TRIM(COALESCE("Included in MA", '')) = 'No' AND TRIM(COALESCE("Monotherapy/combination", '')) = 'Monotherapy' AND TRIM(COALESCE("Trial phase", '')) = 'Phase 3';

ground_truth_sql:
WITH base AS (
SELECT "NCT", "PubMed ID", "Trial name", "Name of ICI" AS source_value FROM clinical_trials WHERE LOWER(TRIM(COALESCE("Name of ICI", ''))) NOT IN ('', 'none', 'null', 'nan') AND TRIM(COALESCE("Included in MA", '')) = 'No' AND TRIM(COALESCE("Monotherapy/combination", '')) = 'Monotherapy' AND TRIM(COALESCE("Trial phase", '')) = 'Phase 3'
)
SELECT "NCT", "PubMed ID", "Trial name", source_value, derive_ici_brand_name(source_value) AS "brand_name"
FROM base;
